mapper.select:
SELECT COUNT(*)
FROM word_notebooks
WHERE id = #{notebookId}
  AND user_id = #{userId}

mapper.update:
UPDATE word_notebooks
SET updated_at = CURRENT_TIMESTAMP
WHERE id = #{notebookId}
  AND user_id = #{userId}

mapper.select:
SELECT DISTINCT n.id
FROM word_notebook_entries e
JOIN word_notebooks n ON n.id = e.word_notebook_id
WHERE n.user_id = #{userId}
  AND e.normalized_word = #{normalizedWord}

mapper.delete:
DELETE e
FROM word_notebook_entries e
JOIN word_notebooks n ON n.id = e.word_notebook_id
WHERE n.user_id = #{userId}
  AND e.normalized_word = #{normalizedWord}
